/** Floor surface under a footstep */
enum class EUOFootstepSurface : uint8
{
	Carpet,
	Tile
};

/** Background music the local player should hear */
enum class EUOMusicTrack : uint8
{
	None,
	/** Cheerful corporate muzak (main menu) */
	Menu,
	/** Detuned, darker take on the same loop (overtime and evaluation) */
	Dark
};

/** What an interaction does, as far as its sounds are concerned */
enum class EUOInteractionSoundAction : uint8
{
	PickUp,
	Deliver,
	Work
};

/** Sounds of one interaction; NAME_None = no sound for that moment */
struct FUOInteractionSounds
{
	/** One-shot when a hold starts (or right before an instant press completes) */
	FName Start;
	/** Loop while holding */
	FName Loop;
	/** One-shot on success */
	FName Complete;
	/** Second one-shot layered on success (item pickups) */
	FName CompleteExtra;
};

/** One sound of the evaluation reveal, played Delay seconds after the evaluation starts */
struct FUORevealCue
{
	float Delay = 0.f;
	FName Sound;
};

struct FUOAudioRules
{
	/** Seconds between the day ending and the first star of the reveal, per opening sound */
	static constexpr float RevealStartPlain = 0.8f;
	static constexpr float RevealStartAfterFanfare = 2.2f;
	static constexpr float RevealStartAfterClosingBell = 2.8f;
	static constexpr float RevealStarInterval = 0.45f;

	static constexpr float MinCreakDelay = 15.f;
	static constexpr float MaxCreakDelay = 40.f;

	/** Floor material name -> surface ("MI_LobbyTile" -> Tile, "MI_Carpet_Dark" -> Carpet; unknown -> Carpet) */
	static EUOFootstepSurface GetSurfaceForMaterial(const FString& MaterialName);

	static FName GetFootstepSound(EUOFootstepSurface Surface);

	/** Distance walked between two footsteps (cm) for a ground speed (cm/s): longer strides when faster */
	static float GetStrideLength(float Speed);

	/** Menu muzak before the day, silence during the shift, the dark version in overtime and evaluation */
	static EUOMusicTrack SelectMusic(EUODayPhase Phase);

	/** The break room radio plays the muzak quietly during the regular shift only */
	static bool IsKitchenRadioOn(EUODayPhase Phase);

	/** Station + action -> start / loop / complete sounds */
	static FUOInteractionSounds GetInteractionSounds(EUOStationType Station, EUOInteractionSoundAction Action);

	/** 0..1 smoothstep of the overtime mood (same curve as the lights); 1 when BlendSeconds <= 0 */
	static float GetOvertimeBlend(float OvertimeSeconds, float BlendSeconds);

	/** Seconds until the next overtime creak/knock for a uniform random value in 0..1 */
	static float GetNextCreakDelay(float Random01);

	/** Evaluation sounds for the local employee: closing bell or fanfare, one rising ping per star, a thud when fired */
	static TArray<FUORevealCue> BuildEvaluationReveal(int32 Stars, EUOStarConsequence Consequence, bool bForceClosed, bool bAllTasksDone);
};
